python3 -c "
import json
with open('map_data.json', 'r') as f:
    data = json.load(f)

high_value = []
for tid, tile in data['tiles'].items():
    score = 0
    if tile['feature'] == 'FEATURE_GEOTHERMAL_FISSURE':
        score += 2
    if tile['feature'] == 'FEATURE_REEF':
        score += 2
    if 'MOUNTAIN' in tile['terrain']:
        score += 1

    if score > 0:
        high_value.append((tid, tile, score))

for tid, tile, score in sorted(high_value, key=lambda x: -x[2])[:20]:
    x, y = int(tid) % data['width'], int(tid) // data['width']
    print(f'Tile {tid} ({x}, {y}): Score {score}, Terrain {tile[\"terrain\"]}, Feature {tile[\"feature\"]}, River {tile[\"is_river\"]}')
"
